package factory

import (
	"context"
	"encoding/json"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/formalize"
	"github.com/gitdek/invariant/internal/github"
	"github.com/gitdek/invariant/internal/project"
)

func classify857(t *testing.T, p *formalize.Proposal, value string) {
	t.Helper()
	b, _ := json.Marshal(p.Statements)
	var rows []map[string]any
	if err := json.Unmarshal(b, &rows); err != nil {
		t.Fatal(err)
	}
	for _, s := range rows {
		if s["kind"] == "bug" {
			delete(s, "code_behavior")
			if value != "" {
				s["code_behavior"] = value
			}
		}
	}
	b, _ = json.Marshal(rows)
	p.Statements = nil
	if err := json.Unmarshal(b, &p.Statements); err != nil {
		t.Fatal(err)
	}
	for _, s := range p.Statements {
		if s.Kind == project.Bug && s.CodeBehavior != value {
			t.Fatalf("proposal lost classification: %+v", s)
		}
	}
	p.Hash = project.ProposalHash(p.Bounds, p.Statements)
}

func TestProposalAndRatificationBindBugClassification857(t *testing.T) {
	p := bufferProposal(t)
	classify857(t, p, "current")
	before := *p
	before.Statements = append([]project.Statement(nil), p.Statements...)
	body := proposalComment(p, nil, Marker{Kind: KindProposal, Proposal: p})
	if !strings.Contains(body, "current") || !strings.Contains(body, "PutWhenFull") {
		t.Errorf("proposal hides current-code classification: %s", body)
	}
	lock := project.Lock{Bounds: p.Bounds, Statements: p.Statements, Ratified: &project.Ratification{By: "gitdek", Issue: 857, Comment: "https://github.com/o/r/issues/857#issuecomment-1", Proposal: p.Hash}}
	gh := fakeComments{perms: map[string]string{"gitdek": "write"}, comments: map[int64]github.Comment{1: {ID: 1, User: github.User{Login: "gitdek"}, IssueURL: "https://api.github.com/repos/o/r/issues/857", Body: "/invariant ratify " + strings.TrimPrefix(p.Hash, "sha256:")}}}
	if err := VerifyRatification(context.Background(), gh, "o/r", lock); err != nil {
		t.Fatal(err)
	}
	for _, value := range []string{"hypothetical", ""} {
		classify857(t, p, value)
		lock.Statements = p.Statements
		if err := VerifyRatification(context.Background(), gh, "o/r", lock); err == nil {
			t.Errorf("classification %q can replace ratified current without ratification", value)
		}
		c := &formalize.Current{ModuleText: before.ModuleText, Includes: before.Includes, Lock: project.Lock{Bounds: before.Bounds, Statements: before.Statements}}
		p.Target = &formalize.Target{Dir: "examples/buffer", Previous: "#1", Amends: before.Hash}
		changes := formalize.Diff(c, p)
		// This is the actual factory amendment rendering, including old/new words.
		body = amendmentComment(p, nil, changes, Marker{Kind: KindProposal, Proposal: p})
		if !strings.Contains(body, "current") || (value != "" && !strings.Contains(body, value)) || strings.Contains(body, "No statement changes") {
			t.Errorf("amendment hides classification %q: %s", value, body)
		}
	}
}

sources.internal/formalize/bug_classification_85:
package formalize

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/project"
)

func draft857(t *testing.T, classification string) string {
	t.Helper()
	ws := workspace(t, nil)
	b, err := os.ReadFile(filepath.Join(ws, "proposal.json"))
	if err != nil {
		t.Fatal(err)
	}
	var d map[string]any
	if err = json.Unmarshal(b, &d); err != nil {
		t.Fatal(err)
	}
	for _, v := range d["statements"].([]any) {
		s := v.(map[string]any)
		if s["kind"] == "bug" {
			delete(s, "code_behavior")
			if classification != "" {
				s["code_behavior"] = classification
			}
		}
	}
	b, err = json.Marshal(d)
	if err != nil {
		t.Fatal(err)
	}
	if err = os.WriteFile(filepath.Join(ws, "proposal.json"), b, 0600); err != nil {
		t.Fatal(err)
	}
	return ws
}

func TestNewProposalsMustClassifyBugs857(t *testing.T) {
	for _, classification := range []string{"", "current", "hypothetical", "plausible"} {
		p, err := Read(draft857(t, classification))
		valid := classification == "current" || classification == "hypothetical"
		if valid && err == nil {
			for _, s := range p.Statements {
				if s.Kind == project.Bug && s.CodeBehavior != classification {
					t.Fatalf("draft lost classification: %+v", s)
				}
			}
		}
		if (err == nil) != valid {
			t.Errorf("new proposal classification %q: proposal=%v err=%v", classification, p, err)
		}
		if !valid && err != nil && !strings.Contains(err.Error(), "code_behavior") {
			t.Errorf("missing named classification diagnostic: %v", err)
		}
	}
	prompt := Prompt(Request{Repo: "owner/repo", Issue: 857, Title: "Fix an existing overflow", Body: "The code overfills the buffer."}, 4)
	for _, word := range []string{"code_behavior", "current", "hypothetical", "unchanged code", "tests"} {
		if !strings.Contains(prompt, word) {
			t.Errorf("formalization prompt omits %q", word)
		}
	}
}

func TestClassificationChangesAreVisibleStatementAmendments857(t *testing.T) {
	p, err := Read(draft857(t, "current"))
	if err != nil {
		t.Fatal(err)
	}
	c := &Current{ModuleText: p.ModuleText, Includes: p.Includes, Lock: project.Lock{Bounds: p.Bounds, Statements: append([]project.Statement(nil), p.Statements...)}}
	for _, classification := range []string{"hypothetical", ""} {
		// Removal is diffable even though a new unclassified draft is refused.
		q := *p
		b, _ := json.Marshal(p.Statements)
		var rows []map[string]any
		if err = json.Unmarshal(b, &rows); err != nil {
			t.Fatal(err)
		}
		for _, s := range rows {
			if s["kind"] == "bug" {
				delete(s, "code_behavior")
				if classification != "" {
					s["code_behavior"] = classification
				}
			}
		}
		b, _ = json.Marshal(rows)
		q.Statements = nil
		if err = json.Unmarshal(b, &q.Statements); err != nil {
			t.Fatal(err)
		}
		for _, s := range q.Statements {
			if s.Kind == project.Bug && s.CodeBehavior != classification {
				t.Fatalf("amendment did not retain classification %q: %+v", classification, s)
			}
		}
		d := Diff(c, &q)
		changed := d.Of(Changed)
		if len(changed) != 1 || changed[0].Name != "PutWhenFull" || changed[0].OwnTextSame() {
			t.Errorf("classification %q is hidden as an unchanged/helper-only statement: %+v", classification, d)
		}
		if project.ProposalHash(q.Bounds, q.Statements) == p.Hash {
			t.Errorf("classification %q keeps old ratification", classification)
		}
	}
}

sources.internal/project/bug_classification_857_:
package project

import (
	"encoding/json"
	"strings"
	"testing"
)

func statement857(t *testing.T, classification string) Statement {
	t.Helper()
	raw := `{"name":"Overflow","kind":"bug","says":"The existing producer overfills the buffer.","expect":"Safe","sha256":"sha256:pin"`
	if classification != "" {
		raw += `,"code_behavior":"` + classification + `"`
	}
	var s Statement
	if err := json.Unmarshal([]byte(raw+`}`), &s); err != nil {
		t.Fatal(err)
	}
	return s
}

func TestBugClassificationIsRatifiedWithoutRehashingLegacy857(t *testing.T) {
	bounds := map[string]string{"Cap": "2"}
	old := statement857(t, "")
	// This is the exact pre-change serialization, independently fixed here.
	want := `{"name":"Overflow","kind":"bug","says":"The existing producer overfills the buffer.","expect":"Safe","sha256":"sha256:pin"}`
	b, err := json.Marshal(old)
	if err != nil || string(b) != want {
		t.Fatalf("legacy statement changed: %s, %v", b, err)
	}
	const legacyHash = "sha256:62006a0448bc4da9e96bc198e320cd41a918bb2ead511405b242d40cf5261e92"
	if got := ProposalHash(bounds, []Statement{old}); got != legacyHash {
		t.Fatalf("legacy proposal hash changed: %s", got)
	}
	seen := map[string]bool{legacyHash: true}
	for _, classification := range []string{"current", "hypothetical"} {
		s := statement857(t, classification)
		if s.CodeBehavior != classification {
			t.Fatalf("classification did not reach the statement API: %+v", s)
		}
		b, _ := json.Marshal(s)
		if !strings.Contains(string(b), `"code_behavior":"`+classification+`"`) {
			t.Errorf("classification lost: %s", b)
		}
		hash := ProposalHash(bounds, []Statement{s})
		if seen[hash] {
			t.Errorf("%s classification does not change ratification identity", classification)
		}
		seen[hash] = true
		var round Statement
		if err := json.Unmarshal(b, &round); err != nil {
			t.Fatal(err)
		}
		if ProposalHash(bounds, []Statement{round}) != hash {
			t.Fatal("classification changed in lock round trip")
		}
	}
}

func TestBugClassificationValidationKeepsLegacyLocks857(t *testing.T) {
	m := Manifest{Module: "M.tla", Code: "src", Language: "typescript", Conformance: "driver.ts"}
	for _, classification := range []string{"", "current", "hypothetical", "Current", "unknown"} {
		l := Lock{Bounds: map[string]string{"Cap": "2"}, Statements: []Statement{{Name: "Spec", Kind: Spec}, {Name: "Safe", Kind: Invariant}, statement857(t, classification)}}
		err := Validate(m, l)
		valid := classification == "" || classification == "current" || classification == "hypothetical"
		if (err == nil) != valid {
			t.Errorf("classification %q: %v", classification, err)
		}
		if !valid && err != nil && !strings.Contains(err.Error(), "code_behavior") {
			t.Errorf("error doesn't identify code_behavior: %v", err)
		}
	}
	for _, kind := range []string{Spec, Invariant, Witness, Fairness, Property} {
		s := statement857(t, "current")
		s.Kind = kind
		s.Name = "Annotated"
		s.Expect = ""
		ss := []Statement{{Name: "Spec", Kind: Spec}, {Name: "Safe", Kind: Invariant}, s}
		if kind == Spec {
			ss = ss[1:]
		}
		if err := Validate(m, Lock{Bounds: map[string]string{"Cap": "2"}, Statements: ss}); err == nil || !strings.Contains(err.Error(), "code_behavior") {
			t.Errorf("non-bug %s accepts classification: %v", kind, err)
		}
	}
}

sources.internal/receipt/bug_replay_857_accept_t:
package receipt

import (
	"encoding/json"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/verify"
)

func TestBugReceiptSeparatesModelAndReplayEvidence857(t *testing.T) {
	const raw = `{"project":"mixed bugs","passed":false,"design":{"passed":true,"outcome":"passed"},"bugs":[{"name":"Old","label":"old","caught":true,"violated":"Safe","steps":2},{"name":"Possible","label":"possible","code_behavior":"hypothetical","caught":true,"violated":"Safe"},{"name":"Actual","label":"actual","code_behavior":"current","caught":true,"violated":"Safe","replay":{"required":true,"status":"replay-unavailable","message":"No execution adapter is available."}}],"code":{"verifier":"Gobra","passed":true,"functions":["KeepSafe"]}}`
	var r verify.Report
	if err := json.Unmarshal([]byte(raw), &r); err != nil {
		t.Fatal(err)
	}
	if r.Bugs[2].CodeBehavior != "current" {
		t.Fatal("receipt lost the ratified classification")
	}
	md := Markdown(&r)
	for _, s := range []string{"not replayed: not classified", "hypothetical", "replay-unavailable", "actual", "proved"} {
		if !strings.Contains(md, s) {
			t.Errorf("receipt omits %q:\n%s", s, md)
		}
	}
	b, err := json.Marshal(r)
	if err != nil {
		t.Fatal(err)
	}
	var view struct {
		Bugs []struct {
			Name         string
			ReplayStatus struct {
				Status, Label      string
				Required, Replayed bool
			} `json:"replay_status"`
		}
	}
	if err = json.Unmarshal(b, &view); err != nil {
		t.Fatal(err)
	}
	if len(view.Bugs) != 3 {
		t.Fatal(string(b))
	}
	for _, bug := range view.Bugs {
		if bug.ReplayStatus.Replayed {
			t.Errorf("%s counted as replayed without an execution", bug.Name)
		}
		if bug.Name == "Old" && (bug.ReplayStatus.Label != "not replayed: not classified" || bug.ReplayStatus.Required) {
			t.Errorf("legacy bug status: %+v", bug)
		}
		if bug.Name == "Actual" && (!bug.ReplayStatus.Required || bug.ReplayStatus.Status != "replay-unavailable") {
			t.Errorf("mandatory unmet replay hidden: %+v", bug)
		}
	}
	before := verify.Fingerprint(r)
	var round verify.Report
	if err = json.Unmarshal(b, &round); err != nil {
		t.Fatal(err)
	}
	if verify.Fingerprint(round) != before {
		t.Fatal("derived replay labels change evidence on JSON round trip")
	}
	if r.CodeAssurance() != "proved" {
		t.Fatal("unmet replay erases independent proof")
	}
}

sources.internal/scope/bug_classification_857_ac:
package scope

import (
	"context"
	"encoding/json"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/project"
)

func TestScopeRejectsReclassificationUnderOldRatification857(t *testing.T) {
	for _, replacement := range []string{"hypothetical", ""} {
		dir := repo(t)
		var old project.Lock
		if err := json.Unmarshal([]byte(`{"bounds":{"Cap":"2"},"statements":[{"name":"Overflow","kind":"bug","says":"Overfills.","expect":"Safe","sha256":"pin","code_behavior":"current"}]}`), &old); err != nil {
			t.Fatal(err)
		}
		if old.Statements[0].CodeBehavior != "current" {
			t.Fatal("ratification lost its current-code classification")
		}
		// The original base can remain legacy; the amendment adds these rules.
		base := project.Lock{Decision: "D-0001"}
		old.Ratified = &project.Ratification{By: "gitdek", Issue: 7, Comment: "https://example.com/c", Amends: project.ProposalHash(base.Bounds, base.Statements), Proposal: project.ProposalHash(old.Bounds, old.Statements)}
		b, _ := json.Marshal(old)
		var raw map[string]any
		if err := json.Unmarshal(b, &raw); err != nil {
			t.Fatal(err)
		}
		s := raw["statements"].([]any)[0].(map[string]any)
		delete(s, "code_behavior")
		if replacement != "" {
			s["code_behavior"] = replacement
		}
		b, _ = json.Marshal(raw)
		write(t, dir, map[string]string{"examples/01-old/.invariant/ratified.lock": string(b)})
		commit(t, dir, "classification changed after ratification")
		r, err := Check(context.Background(), dir, "main", "HEAD", 7)
		if err != nil {
			t.Fatal(err)
		}
		if r.OK() || !strings.Contains(strings.Join(r.Problems, " "), "isn't the proposal that was ratified") {
			t.Errorf("classification %q escapes scope ratification: %+v", replacement, r)
		}
	}
}

sources.internal/tlc/replay_path_857_accept_test:
package tlc

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"
)

// ExtractReplay checks an existing fresh counterexample, never searches for a
// shorter substitute. ReplaySpec has Module, Bug, Expect, ExpectKind and Config.
// ReplayPath has Version, ID, Module, Bug, BugPin, Expect, ExpectKind,
// Specification, ModelSHA256, IncludesSHA256, Bounds, Tool,
// States ([]ReplayState, a map[string]ReplayValue), Steps ([]ReplayStep with
// From/To zero-based state indexes, Action, Args and Bug), Offending (zero-based
// first bug step), Loop (TLC's one-based target), and Stutters.
// The tool wrapper proves Init and every exact edge under Next OR the named
// bug and establishes the expected violation; it emits one checked candidate
// set per edge as <<"invariant-replay-v1", edgeIndex, {<<action, args, bug>>}>>.
// Exactly one semantic action/argument interpretation is required. Human
// labels are deliberately wrong below. Missing/duplicate/ambiguous evidence,
// malformed values/states, wrong violations and unsupported temporal paths
// return named errors, with no partial executable request.

const model857 = `---- MODULE ReplayFixture ----
EXTENDS Naturals, Sequences, Local
CONSTANT People
VARIABLE n, history
vars == <<n, history>>
Init == n = 0 /\ history = <<>>
Put(p) == n < 3 /\ n' = n + 1 /\ history' = Append(history,p)
Done == n = 3 /\ UNCHANGED vars
Next == (\E p \in People : Put(p)) \/ Done
Spec == Init /\ [][Next]_vars
Safe == n <= 3 /\ Helper
Eventually == <> (n = 3)
BadDrop(p) == n = 3 /\ n' = 4 /\ history' = Append(history,p)
BadReset(p) == n = 3 /\ n' = 5 /\ history' = Append(history,p)
Bad == \E p \in People : BadDrop(p)
OtherBad == \E p \in People : BadReset(p)
====
`

func init() {
	if os.Getenv("INVARIANT_REPLAY857_DOUBLE") == "1" {
		os.Exit(replayDocker857(os.Args[1:]))
	}
}

func replayDocker857(args []string) int {
	if len(args) == 0 {
		return 90
	}
	if args[0] == "rm" || args[0] == "image" {
		return 0
	}
	if args[0] != "run" {
		return 91
	}
	work := ""
	all := strings.Join(args, " ")
	for i, a := range args {
		if a == "-v" && i+1 < len(args) {
			p := strings.Split(args[i+1], ":")
			if len(p) > 1 && p[1] == "/work" {
				work = p[0]
			}
		}
	}
	if work == "" || !strings.Contains(all, "--network none") || !strings.Contains(all, "-workers 1") || !strings.Contains(all, "replay857-java") {
		return 92
	}
	model, err := os.ReadFile(filepath.Join(work, "ReplayFixture.tla"))
	if err != nil || string(model) != model857 {
		return 93
	}
	inc, err := os.ReadFile(filepath.Join(work, "Local.tla"))
	if err != nil || !strings.Contains(string(inc), "Helper == TRUE") {
		return 94
	}
	cfg, err := os.ReadFile(filepath.Join(work, "Invariant.cfg"))
	if err != nil || !strings.Contains(string(cfg), "CONSTANT People = {p1, p2}") {
		return 95
	}
	module := args[len(args)-1]
	body, err := os.ReadFile(filepath.Join(work, module))
	if err != nil {
		return 96
	}
	log := os.Getenv("INVARIANT_REPLAY857_LOG")
	f, err := os.OpenFile(log, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0600)
	if err != nil {
		return 97
	}
	encoded, _ := json.Marshal(map[string]any{"args": args, "body": string(body), "config": string(cfg)})
	f.Write(append(encoded, '\n'))
	f.Close()
	msg := func(code int, body string) {
		fmt.Printf("@!@!@STARTMSG %d:0 @!@!@\n%s\n@!@!@ENDMSG %d @!@!@\n", code, body, code)
	}
	mode := os.Getenv("INVARIANT_REPLAY857_MODE")
	if mode == "tool-error" {
		msg(1000, "replay check failed")
		return 150
	}
	if mode == "wrong-edge" {
		msg(2110, "Invariant ReplayEdge is violated.")
		return 12
	}
	last := "BadDrop"
	if strings.Contains(string(body), "OtherBad") {
		last = "BadReset"
	}
	for i, row := range []string{`{<<"Put", <<p1>>, FALSE>>}`, `{<<"Put", <<p2>>, FALSE>>}`, `{<<"Put", <<p1>>, FALSE>>}`, `{<<"` + last + `", <<p2>>, TRUE>>}`} {
		if mode == "missing" && i == 1 {
			continue
		}
		if mode == "ambiguous" && i == 1 {
			row = `{<<"Put", <<p1>>, FALSE>>, <<"Put", <<p2>>, FALSE>>}`
		}
		if mode == "malformed" && i == 1 {
			row = `{<<"Put", <<p2>> >>}`
		}
		fmt.Printf("<<\"invariant-replay-v1\", %d, %s>>\n", i, row)
		if mode == "duplicate" && i == 1 {
			fmt.Printf("<<\"invariant-replay-v1\", %d, %s>>\n", i, row)
		}
	}
	msg(2193, "Model checking completed. No error has been found.")
	msg(2199, "5 states generated, 5 distinct states found, 0 states left on queue.")
	msg(2186, "Finished.")
	return 0
}

func replayFixture857(t *testing.T) (Runner, string, ReplaySpec, Result, string) {
	t.Helper()
	dir := t.TempDir()
	for name, body := range map[string]string{"ReplayFixture.tla": model857, "Local.tla": "---- MODULE Local ----\nHelper == TRUE\n====\n", "tools.jar": "fixture jar bytes"} {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0600); err != nil {
			t.Fatal(err)
		}
	}
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	bin := t.TempDir()
	launcher := "#!/bin/sh\nexec '" + strings.ReplaceAll(exe, "'", "'\"'\"'") + "' \"$@\"\n"
	if err = os.WriteFile(filepath.Join(bin, "docker"), []byte(launcher), 0700); err != nil {
		t.Fatal(err)
	}
	log := filepath.Join(dir, "calls.jsonl")
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	t.Setenv("INVARIANT_REPLAY857_DOUBLE", "1")
	t.Setenv("INVARIANT_REPLAY857_LOG", log)
	t.Setenv("INVARIANT_REPLAY857_MODE", "")
	r := Result{Outcome: Violated, Invariant: "Safe", Version: "TLC fixture"}
	for i, h := range []string{"<<>>", "<<p1>>", "<<p1,p2>>", "<<p1,p2,p1>>", "<<p1,p2,p1,p2>>"} {
		r.Trace = append(r.Trace, State{Index: i + 1, Action: "MisleadingAlias", Vars: []Var{{Name: "n", Value: fmt.Sprint(i)}, {Name: "history", Value: h}}})
	}
	s := ReplaySpec{Module: "ReplayFixture", Bug: "Bad", Expect: "Safe", ExpectKind: "invariant", Config: Config{Specification: "Spec", Constants: map[string]string{"People": "{p1, p2}"}, Invariants: []string{"Safe"}}}
	return Runner{Image: "replay857-java", Jar: filepath.Join(dir, "tools.jar")}, dir, s, r, log
}

func TestReplayPathsUseEveryCheckedParameterizedEdge857(t *testing.T) {
	runner, dir, s, trace, log := replayFixture857(t)
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	p, err := runner.ExtractReplay(ctx, dir, s, trace)
	if err != nil {
		t.Fatal(err)
	}
	if p.Version != 1 || p.ID == "" || len(p.States) != 5 || len(p.Steps) != 4 || p.Offending != 3 {
		t.Fatalf("incomplete path: %+v", p)
	}
	if p.Bug != s.Bug || p.Expect != s.Expect || p.ExpectKind != s.ExpectKind || p.Specification != s.Config.Specification || p.BugPin == "" {
		t.Fatalf("path does not bind its exact bug and expected violation: %+v", p)
	}
	for i, step := range p.Steps {
		want := "Put"
		if i == 3 {
			want = "BadDrop"
		}
		arg := "p1"
		if i == 1 || i == 3 {
			arg = "p2"
		}
		if step.From != i || step.To != i+1 || step.Action != want || len(step.Args) != 1 || step.Args[0].Kind != "model" || step.Args[0].Atom != arg || step.Bug != (i == 3) {
			t.Errorf("edge %d: %+v", i, step)
		}
	}
	if p.ModelSHA256 == "" || p.IncludesSHA256["Local.tla"] == "" || p.Tool.JarSHA256 == "" || p.Tool.Image != "replay857-java" || p.Bounds["People"] != "{p1, p2}" {
		t.Fatalf("path lacks exact source/tool/bounds binding: %+v", p)
	}
	again, err := runner.ExtractReplay(ctx, dir, s, trace)
	if err != nil || again.ID != p.ID {
		t.Fatalf("path identity is not deterministic: %v", err)
	}
	other := s
	other.Bug = "OtherBad"
	secondTrace := trace
	secondTrace.Trace = append([]State(nil), trace.Trace...)
	secondTrace.Trace[4].Vars = []Var{{Name: "n", Value: "5"}, {Name: "history", Value: "<<p1,p2,p1,p2>>"}}
	q, err := runner.ExtractReplay(ctx, dir, other, secondTrace)
	if err != nil {
		t.Fatal(err)
	}
	if q.ID == p.ID || q.Steps[3].Action != "BadReset" || !reflect.DeepEqual(q.States[:4], p.States[:4]) {
		t.Fatalf("two bugs share/rewrite a replay: %+v %+v", p, q)
	}
	trace.Trace[0].Vars[0].Value = "99"
	if p.States[0]["n"].Atom != "0" {
		t.Fatal("retained path aliases caller trace")
	}
	b, err := os.ReadFile(log)
	if err != nil || len(strings.Split(strings.TrimSpace(string(b)), "\n")) < 3 {
		t.Fatal("path action interpretations never reached TLC")
	}
}

func TestReplayPathsRefuseMalformedAmbiguousAndTemporalEvidence857(t *testing.T) {
	runner, dir, s, trace, _ := replayFixture857(t)
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	for _, mode := range []string{"missing", "duplicate", "ambiguous", "malformed", "wrong-edge", "tool-error"} {
		t.Setenv("INVARIANT_REPLAY857_MODE", mode)
		if _, err := runner.ExtractReplay(ctx, dir, s, trace); err == nil {
			t.Errorf("accepted %s action/edge evidence", mode)
		}
	}
	t.Setenv("INVARIANT_REPLAY857_MODE", "")
	for _, edit := range []func(*Result){
		func(r *Result) { r.Invariant = "Other" }, func(r *Result) { r.Trace = nil },
		func(r *Result) { r.Trace[2].Index = 4 },
		func(r *Result) { r.Trace[1].Vars = append(r.Trace[1].Vars, Var{Name: "n", Value: "3"}) },
		func(r *Result) { r.Trace[1].Vars = r.Trace[1].Vars[:1] },
	} {
		b, _ := json.Marshal(trace)
		var bad Result
		if err := json.Unmarshal(b, &bad); err != nil {
			t.Fatal(err)
		}
		edit(&bad)
		if _, err := runner.ExtractReplay(ctx, dir, s, bad); err == nil {
			t.Errorf("accepted malformed trace: %+v", bad)
		}
	}
	for _, stutter := range []bool{false, true} {
		temporal := trace
		temporal.Outcome = PropertyViolated
		temporal.Invariant = ""
		temporal.Property = "Eventually"
		temporal.Stutters = stutter
		if !stutter {
			temporal.Loop = 2
		}
		ts := s
		ts.Expect = "Eventually"
		ts.ExpectKind = "property"
		p, err := runner.ExtractReplay(ctx, dir, ts, temporal)
		if err == nil || !strings.Contains(err.Error(), "replay-unsupported-temporal") || p.Loop != temporal.Loop || p.Stutters != stutter {
			t.Errorf("temporal behavior reduced to a finite success: %+v %v", p, err)
		}
	}
}

sources.internal/tlc/replay_value_857_accept_tes:
package tlc

import (
	"encoding/json"
	"reflect"
	"testing"
)

// ReplayValue is a tagged lossless value: Kind is bool, integer, string,
// model, set, sequence, record or function; Atom holds scalar text, Elements
// holds set/sequence members, and Entries holds typed Key/Value pairs.
// TLA renders only validated data, never unchecked source expressions.
// Set members and record/function entries canonicalize; sequences do not.
// ParseValue remains the existing display API with its existing tests intact.
func TestReplayValuesPreserveTypesAndExactIntegers857(t *testing.T) {
	cases := []struct{ source, kind, atom string }{
		{`r1`, "model", "r1"}, {`"r1"`, "string", "r1"}, {`TRUE`, "bool", "TRUE"},
		{`9007199254740993`, "integer", "9007199254740993"}, {`-9223372036854775809`, "integer", "-9223372036854775809"},
		{`{r1, "r1"}`, "set", ""}, {`<<r1, "r1">>`, "sequence", ""},
		{`[a |-> <<1, 2>>, b |-> {r1}]`, "record", ""},
		{`(r1 :> 1 @@ "r1" :> 2 @@ <<1, 2>> :> 3)`, "function", ""},
	}
	for _, tc := range cases {
		v, err := ParseReplayValue(tc.source)
		if err != nil {
			t.Fatal(err)
		}
		if v.Kind != tc.kind || v.Atom != tc.atom {
			t.Errorf("%s loses type/value: %+v", tc.source, v)
		}
		b, err := json.Marshal(v)
		if err != nil {
			t.Fatal(err)
		}
		var round ReplayValue
		if err = json.Unmarshal(b, &round); err != nil {
			t.Fatal(err)
		}
		text, err := round.TLA()
		if err != nil {
			t.Fatal(err)
		}
		back, err := ParseReplayValue(text)
		if err != nil || !reflect.DeepEqual(v, back) {
			t.Errorf("%s changes across JSON/TLA: %s %+v %v", tc.source, text, back, err)
		}
	}
	for _, pair := range [][2]string{{`{r1, "r1"}`, `{"r1", r1}`}, {`1..3`, `{3, 1, 2}`}, {`(r1 :> 1 @@ "r1" :> 2)`, `("r1" :> 2 @@ r1 :> 1)`}} {
		a, e1 := ParseReplayValue(pair[0])
		b, e2 := ParseReplayValue(pair[1])
		if e1 != nil || e2 != nil || !reflect.DeepEqual(a, b) {
			t.Errorf("equal TLA values have different encoding: %v %v %v %v", a, b, e1, e2)
		}
	}
	a, _ := ParseReplayValue(`<<1,2>>`)
	b, _ := ParseReplayValue(`<<2,1>>`)
	if reflect.DeepEqual(a, b) {
		t.Fatal("sequence order lost")
	}
	for _, bad := range []string{`(r1 :> 1 @@ r1 :> 2)`, `[a |-> 1, a |-> 2]`, `<<1`, `1.5`, `1 /\ TRUE`, `"unterminated`} {
		if _, err := ParseReplayValue(bad); err == nil {
			t.Errorf("accepted malformed/ambiguous replay value %q", bad)
		}
	}
}

sources.internal/verify/replaytest/bug_replay_co:
package replaytest

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/tlc"
	"github.com/gitdek/invariant/internal/verify"
)

// Version 1 request/result contract, shared by subsequent adapters:
// NewBugReplayRequest(statement, proposalHash, checkedPath) returns an owned
// request with Version, ID (stable content identity), InvocationID (fresh),
// Bug (the complete ratified statement), Proposal and Path. Only current bugs
// and valid bound paths qualify. The path and expected verdict come from the
// gate; neither a driver nor a random search may replace them.
//
// BugReplayResult has Version, RequestID, InvocationID, Outcome, Initial,
// Calls. Outcome is complete, refused, reproduced or failed. Each
// BugReplayCall has Index, Action, Args, Before, After, Dispatched, Outcome
// (returned, refused or failed) and Error. A refusal here is a normally
// completed, explicitly observed operation refusal; an exception is Error,
// never a successful refusal. BugReplayObservation independently supplies
// RequestID, InvocationID, Initial, Calls, Started, Completed and ExitCode.
// These observations must be factory-owned actual-dispatch evidence supplied
// by an execution adapter, never driver-declared result flags. CheckBugReplay
// validates the result against this independent transcript and the request,
// and asks TLC to check a non-forbidden alternative against the same snapshot
// in Invariant_ReplayResult.tla with Invariant_ReplayAllowed. It returns
// BugReplayEvidence with Required, Status, Passed, Request, Result and Message.
// Evaluating supplied contract records DOES NOT attach gate evidence or turn
// Report.Passed green; this step's real gate has no execution adapter.
//
// Success needs the exact initial state and every prefix call, in order,
// followed by an actually dispatched offending call. Its forbidden result
// is failure (reproduced); a normal refusal or returned alternative must be
// model-allowed and checked. No skipped prefix, early stop, stale invocation,
// missing dispatch, forged refusal, arbitrary exception or changed state is
// success. The full TLC suffix remains retained when its offending call is
// earlier than the final violation; code need reproduce only through the
// offending call, since rejecting it makes that forbidden suffix impossible.

func clone857[T any](t *testing.T, x T) T {
	t.Helper()
	b, e := json.Marshal(x)
	if e != nil {
		t.Fatal(e)
	}
	var y T
	if e = json.Unmarshal(b, &y); e != nil {
		t.Fatal(e)
	}
	return y
}

func successfulResult857(t *testing.T, q verify.BugReplayRequest) (verify.BugReplayResult, verify.BugReplayObservation) {
	t.Helper()
	r := verify.BugReplayResult{Version: 1, RequestID: q.ID, InvocationID: q.InvocationID, Outcome: "refused", Initial: clone857(t, q.Path.States[0])}
	for i, step := range q.Path.Steps[:q.Path.Offending+1] {
		c := verify.BugReplayCall{Index: i, Action: step.Action, Args: clone857(t, step.Args), Before: clone857(t, q.Path.States[step.From]), After: clone857(t, q.Path.States[step.To]), Dispatched: true, Outcome: "returned"}
		if i == q.Path.Offending {
			c.After = clone857(t, c.Before)
			c.Outcome = "refused"
		}
		r.Calls = append(r.Calls, c)
	}
	o := verify.BugReplayObservation{RequestID: q.ID, InvocationID: q.InvocationID, Initial: clone857(t, r.Initial), Calls: clone857(t, r.Calls), Started: true, Completed: true, ExitCode: 0}
	return r, o
}

func TestReplayResultRequiresActualOrderedOffendingCall857(t *testing.T) {
	dir, tc, log := gateFixture857(t, "typescript", []string{"current"}, false)
	r := run857(t, dir, tc, true)
	if r.Bugs[0].Replay == nil || r.Bugs[0].Replay.Request == nil {
		t.Fatal("no prepared request")
	}
	q := *r.Bugs[0].Replay.Request
	runner := tlc.Runner{Image: tc.JavaImage, Jar: tc.TLCJar}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	check := func(result verify.BugReplayResult, observed verify.BugReplayObservation) (verify.BugReplayEvidence, error) {
		return verify.CheckBugReplay(ctx, runner, filepath.Join(dir, ".invariant/specs"), q, result, observed)
	}
	result, observed := successfulResult857(t, q)
	good, err := check(result, observed)
	if err != nil || !good.Passed || good.Status != "refused" {
		t.Fatalf("observed, checked refusal did not satisfy replay contract: %+v %v", good, err)
	}
	// A normally returning actual call may choose another permitted successor.
	alternative := clone857(t, result)
	alternative.Outcome = "complete"
	last := len(alternative.Calls) - 1
	alternative.Calls[last].Outcome = "returned"
	alternative.Calls[last].After = clone857(t, q.Path.States[0])
	alternateObservation := clone857(t, observed)
	alternateObservation.Calls = clone857(t, alternative.Calls)
	good, err = check(alternative, alternateObservation)
	if err != nil || !good.Passed || good.Status != "complete" {
		t.Fatalf("model-allowed actual alternative refused: %+v %v", good, err)
	}
	// Match both records where appropriate: agreement between forged records
	// alone cannot replace the original requested path or actual dispatch.
	cases := []struct {
		name string
		edit func(*verify.BugReplayResult, *verify.BugReplayObservation)
	}{
		{"stale invocation", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.InvocationID = "old"
			o.InvocationID = "old"
		}},
		{"wrong request", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.RequestID = "other"
			o.RequestID = "other"
		}},
		{"wrong version", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) { r.Version = 2 }},
		{"unknown outcome", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) { r.Outcome = "success" }},
		{"changed initial state", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Initial = clone857(t, q.Path.States[1])
			o.Initial = clone857(t, r.Initial)
		}},
		{"skipped setup", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Calls = r.Calls[1:]
			o.Calls = clone857(t, r.Calls)
		}},
		{"reordered setup", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Calls[0], r.Calls[1] = r.Calls[1], r.Calls[0]
			o.Calls = clone857(t, r.Calls)
		}},
		{"missing dispatch", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Calls[last].Dispatched = false
			o.Calls = clone857(t, r.Calls)
		}},
		{"wrong action", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Calls[last].Action = "Done"
			o.Calls = clone857(t, r.Calls)
		}},
		{"wrong typed argument", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Calls[0].Args[0].Kind = "string"
			o.Calls = clone857(t, r.Calls)
		}},
		{"prefix diverged", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Calls[0].After = clone857(t, q.Path.States[0])
			o.Calls = clone857(t, r.Calls)
		}},
		{"premature stop", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Calls = r.Calls[:last]
			o.Calls = clone857(t, r.Calls)
		}},
		{"unfinished process", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) { o.Completed = false }},
		{"failed process", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) { o.ExitCode = 1 }},
		{"no actual invocation", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) { o.Started = false }},
		{"fabricated refusal", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			o.Calls[last].Outcome = "failed"
			o.Calls[last].Error = "ValueError"
		}},
		{"arbitrary exception", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Calls[last].Error = "unrelated network failure"
			o.Calls = clone857(t, r.Calls)
		}},
		{"reproduced bug", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Outcome = "reproduced"
			r.Calls[last].Outcome = "returned"
			r.Calls[last].After = clone857(t, q.Path.States[3])
			o.Calls = clone857(t, r.Calls)
		}},
		{"forbidden state called refusal", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Calls[last].After = clone857(t, q.Path.States[3])
			o.Calls = clone857(t, r.Calls)
		}},
		{"model-disallowed alternative", func(r *verify.BugReplayResult, o *verify.BugReplayObservation) {
			r.Outcome = "complete"
			r.Calls[last].Outcome = "returned"
			v, _ := tlc.ParseReplayValue("99")
			r.Calls[last].After["n"] = v
			o.Calls = clone857(t, r.Calls)
		}},
	}
	for _, tc := range cases {
		rc, oc := clone857(t, result), clone857(t, observed)
		tc.edit(&rc, &oc)
		e, err := check(rc, oc)
		if err == nil && e.Passed {
			t.Errorf("%s satisfied replay: %+v", tc.name, e)
		}
		if tc.name == "reproduced bug" && err == nil && e.Status != "reproduced" {
			t.Errorf("lost reproduced outcome: %+v", e)
		}
	}
	b, e := os.ReadFile(log)
	if e != nil {
		t.Fatal(e)
	}
	if !strings.Contains(string(b), "Invariant_ReplayResult.tla") {
		t.Fatal("allowed/refused code alternatives were never checked by TLC")
	}
	// Results cannot be checked against a different sibling snapshot.
	write857(t, dir, ".invariant/specs/Local.tla", "---- MODULE Local ----\nHelper == FALSE\n====\n")
	if e, err := check(result, observed); err == nil && e.Passed {
		t.Fatal("replay accepted against substituted model includes")
	}
}

func TestReplayIdentityAndFingerprintsBindStableEvidence857(t *testing.T) {
	dir, tc, _ := gateFixture857(t, "typescript", []string{"current"}, false)
	r := run857(t, dir, tc, true)
	if r.Bugs[0].Replay == nil || r.Bugs[0].Replay.Request == nil {
		t.Fatal("no prepared replay")
	}
	q := *r.Bugs[0].Replay.Request
	newRequest, err := verify.NewBugReplayRequest(q.Bug, q.Proposal, q.Path)
	if err != nil {
		t.Fatal(err)
	}
	if newRequest.ID != q.ID || newRequest.InvocationID == "" || newRequest.InvocationID == q.InvocationID {
		t.Fatal("stable request and fresh invocation identities were conflated")
	}
	// Caller mutation after construction must not alter retained requests.
	saved := clone857(t, newRequest)
	q.Path.States[0]["n"] = q.Path.States[1]["n"]
	if newRequest.Path.States[0]["n"].Atom != saved.Path.States[0]["n"].Atom {
		t.Fatal("request aliases caller-owned input")
	}
	q = saved
	result, _ := successfulResult857(t, q)
	r.Bugs[0].Replay.Request = &q
	r.Bugs[0].Replay.Result = &result
	base := verify.Fingerprint(*r)
	volatile := clone857(t, *r)
	volatile.Bugs[0].Trace = "/private/another/trace.json"
	volatile.Bugs[0].Replay.Request.InvocationID = "another-process"
	volatile.Bugs[0].Replay.Result.InvocationID = "another-process"
	volatile.GeneratedAt = "tomorrow"
	if verify.Fingerprint(volatile) != base {
		t.Fatal("private paths/invocation identities changed portable fingerprint")
	}
	for _, edit := range []func(*verify.Report){
		func(r *verify.Report) { r.Bugs[0].CodeBehavior = "hypothetical" },
		func(r *verify.Report) { r.Bugs[0].Replay.Request.Bug.Expect = "Other" },
		func(r *verify.Report) { r.Bugs[0].Replay.Request.Path.IncludesSHA256["Local.tla"] = "changed" },
		func(r *verify.Report) { r.Bugs[0].Replay.Request.Path.Bounds["Limit"] = "4" },
		func(r *verify.Report) { r.Bugs[0].Replay.Request.Path.Tool.JarSHA256 = "changed" },
		func(r *verify.Report) { r.Bugs[0].Replay.Request.Path.Steps[0].Args[0].Atom = "p2" },
		func(r *verify.Report) { r.Bugs[0].Replay.Result.Outcome = "reproduced" },
		func(r *verify.Report) { r.Bugs[0].Replay.Result.Calls[0].Dispatched = false },
	} {
		changed := clone857(t, *r)
		edit(&changed)
		if verify.Fingerprint(changed) == base {
			t.Fatal("stable replay evidence omitted from fingerprint")
		}
	}
	for _, class := range []string{"", "hypothetical"} {
		s := q.Bug
		s.CodeBehavior = class
		if _, e := verify.NewBugReplayRequest(s, q.Proposal, q.Path); e == nil {
			t.Errorf("%q bug created mandatory request", class)
		}
	}
	for _, edit := range []func(*project.Statement){
		func(s *project.Statement) { s.Name = "OtherBug" },
		func(s *project.Statement) { s.Expect = "OtherInvariant" },
		func(s *project.Statement) { s.SHA256 = "sha256:other-pin" },
	} {
		s := q.Bug
		edit(&s)
		if _, e := verify.NewBugReplayRequest(s, q.Proposal, q.Path); e == nil {
			t.Fatal("a path was reassigned to another ratified bug")
		}
	}
}

sources.internal/verify/replaytest/bug_replay_ga:
package replaytest

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/tla"
	"github.com/gitdek/invariant/internal/toolchain"
	"github.com/gitdek/invariant/internal/verify"
	"github.com/gitdek/invariant/internal/verify/internal/pythongatetest"
)

// This is one complete plumbing step. No production replay adapter or public
// Run option may inject successful replay evidence in this change. Every
// current bug of a driver-based gate remains required and fails with the
// named replay-unavailable status; model-only checking prepares its request
// without executing code or changing model success. Go agreement/exploration
// retains its existing meaning. Legacy and hypothetical bugs never request
// replay; missing classification never triggers inference or amendment.
//
// The builder also adds internal/verify/bug_replay_integration_test.go under
// the existing integration tag/lane: real pinned TLC extracts two different
// bug paths, repeated parameterized actions (including an existential bug
// alias), typed values and an offending action before a later violating
// state; checks the exact prefix, Init, bounds/includes/tool bindings; refuses
// nonmatching/ambiguous edges and retains loop/stutter counterexamples with
// replay-unsupported-temporal. No finite lasso prefix proves liveness.
// Existing liveness, assurance and Python gate refusal suites remain intact.
// In particular, pythongatetest's unclassified legacy fixtures stay that way;
// only new-proposal fixtures are classified. The named dashboard assertion
// changes from merely Caught to Caught plus the unclassified replay label.

const gateModel857 = `---- MODULE BugGate ----
EXTENDS Naturals, Local
CONSTANT Limit, People
VARIABLE n
vars == <<n>>
Init == n = 0
Inc(p) == p \in People /\ n < Limit /\ n' = n + 1
Done == n = Limit /\ UNCHANGED n
Reset == n = Limit /\ n' = 0
Next == (\E p \in People : Inc(p)) \/ Done \/ Reset
Spec == Init /\ [][Next]_vars
Safe == n <= Limit /\ Helper
BreakA(p) == p \in People /\ n = Limit /\ n' = Limit + 1
BreakB(p) == p \in People /\ n = Limit /\ n' = Limit + 2
BadA == \E p \in People : BreakA(p)
BadB == \E p \in People : BreakB(p)
====
`

func init() {
	if os.Getenv("INVARIANT_GATE857_DOUBLE") == "1" {
		os.Exit(gateDocker857(os.Args[1:]))
	}
}

func gateDocker857(args []string) int {
	if len(args) == 0 {
		return 90
	}
	if args[0] == "rm" || args[0] == "image" {
		return 0
	}
	if args[0] == "info" {
		return 1
	}
	if args[0] != "run" {
		return 91
	}
	all := strings.Join(args, " ")
	imageArg := func(want string) bool {
		for _, arg := range args {
			if arg == want {
				return true
			}
		}
		return false
	}
	mounts := map[string]string{}
	for i, a := range args {
		if a == "-v" && i+1 < len(args) {
			p := strings.Split(args[i+1], ":")
			if len(p) > 1 {
				mounts[p[1]] = p[0]
			}
		}
	}
	if !strings.Contains(all, "--network none") {
		return 92
	}
	kind := ""
	body := ""
	if strings.Contains(all, "tlc2.TLC") {
		kind = "tlc"
		module := args[len(args)-1]
		b, e := os.ReadFile(filepath.Join(mounts["/work"], module))
		if e != nil {
			return 93
		}
		body = string(b)
	} else if imageArg("gate857-node") {
		kind = "driver"
	} else if imageArg("gate857-go") {
		kind = "go"
	} else if imageArg("gate857-gobra") {
		kind = "proof"
	} else {
		return 94
	}
	f, e := os.OpenFile(os.Getenv("INVARIANT_GATE857_LOG"), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0600)
	if e != nil {
		return 95
	}
	b, _ := json.Marshal(map[string]string{"kind": kind, "body": body, "args": all})
	f.Write(append(b, '\n'))
	f.Close()
	msg := func(code int, body string) {
		fmt.Printf("@!@!@STARTMSG %d:0 @!@!@\n%s\n@!@!@ENDMSG %d @!@!@\n", code, body, code)
	}
	switch kind {
	case "driver":
		if os.Getenv("INVARIANT_GATE857_NO_CODE") == "1" {
			return 96
		}
		recording := `{"traces":[[{"n":0},{"n":1}]]}`
		if os.Getenv("INVARIANT_GATE857_EXHAUSTIVE") == "1" {
			recording = `{"states":[{"n":0},{"n":1},{"n":2}],"init":[0],"attempts":[[0,"Inc",[{"$mv":"p1"}],1],[1,"Inc",[{"$mv":"p1"}],2],[2,"Inc",[{"$mv":"p1"}],2],[0,"Done",[],0],[1,"Done",[],1],[2,"Done",[],2],[0,"Reset",[],0],[1,"Reset",[],1],[2,"Reset",[],0]]}`
		}
		if e := os.WriteFile(filepath.Join(mounts["/out"], "traces.json"), []byte(recording), 0600); e != nil {
			return 97
		}
		fmt.Print("@@invariant test=0\n@@invariant conform=0\n")
		return 0
	case "go":
		fmt.Print("@@invariant vet=0\n@@invariant test=0\ninvariant-agreement states=3 depth=3\n@@invariant agree=0\n")
		return 0
	case "proof":
		fmt.Print("Gobra found 0 errors\n")
		return 0
	}
	module := args[len(args)-1]
	if module == "Invariant_ReplayResult.tla" && strings.Contains(body, "99") {
		msg(2110, "Invariant Invariant_ReplayAllowed is violated.")
		return 12
	}
	if strings.HasPrefix(module, "Bug_") && os.Getenv("INVARIANT_GATE857_MISS_BUG") != "1" {
		msg(2110, "Invariant Safe is violated.")
		for i, n := range []int{0, 1, 2, 3} {
			if strings.Contains(module, "BadB") && i == 3 {
				n = 4
			}
			msg(2217, fmt.Sprintf("%d: <OpaqueAlias line 1, col 1 to line 1, col 2 of module BugGate>\n/\\ n = %d", i+1, n))
		}
		msg(2186, "Finished.")
		return 12
	}
	if strings.Contains(body, "invariant-replay-v1") {
		last := "BreakA"
		if strings.Contains(body, "BadB") {
			last = "BreakB"
		}
		fmt.Print("<<\"invariant-replay-v1\", 0, {<<\"Inc\", <<p1>>, FALSE>>}>>\n<<\"invariant-replay-v1\", 1, {<<\"Inc\", <<p1>>, FALSE>>}>>\n")
		fmt.Printf("<<\"invariant-replay-v1\", 2, {<<\"%s\", <<p1>>, TRUE>>}>>\n", last)
	}
	msg(2193, "Model checking completed. No error has been found.")
	msg(2199, "4 states generated, 3 distinct states found, 0 states left on queue.")
	msg(2194, "The depth of the complete state graph search is 3.")
	msg(2186, "Finished.")
	return 0
}

func write857(t *testing.T, dir, name, body string) {
	t.Helper()
	p := filepath.Join(dir, name)
	if e := os.MkdirAll(filepath.Dir(p), 0700); e != nil {
		t.Fatal(e)
	}
	if e := os.WriteFile(p, []byte(body), 0600); e != nil {
		t.Fatal(e)
	}
}

func gateFixture857(t *testing.T, language string, classes []string, exhaustive bool) (string, toolchain.Toolchain, string) {
	t.Helper()
	dir := t.TempDir()
	includes := map[string]string{"Local.tla": "---- MODULE Local ----\nHelper == TRUE\n====\n"}
	m, err := tla.Read(gateModel857, includes)
	if err != nil {
		t.Fatal(err)
	}
	ss := []project.Statement{{Name: "Spec", Kind: project.Spec, Says: "The counter advances."}, {Name: "Safe", Kind: project.Invariant, Says: "The counter is bounded."}}
	for i, class := range classes {
		name := []string{"BadA", "BadB"}[i]
		raw := map[string]any{"name": name, "kind": "bug", "says": "The counter goes past the limit.", "expect": "Safe"}
		if class != "" {
			raw["code_behavior"] = class
		}
		b, _ := json.Marshal(raw)
		var s project.Statement
		if err = json.Unmarshal(b, &s); err != nil {
			t.Fatal(err)
		}
		ss = append(ss, s)
	}
	for i := range ss {
		ss[i].SHA256, err = m.PinHash(ss[i].Name, project.Model)
		if err != nil {
			t.Fatal(err)
		}
	}
	lock := project.Lock{Decision: "test fixture", Bounds: map[string]string{"Limit": "2", "People": "{p1}"}, Statements: ss}
	lock.Decision = ""
	lock.Ratified = &project.Ratification{By: "fixture", Issue: 857, Proposal: project.ProposalHash(lock.Bounds, lock.Statements)}
	manifest := project.Manifest{Name: "bug replay gate", Module: ".invariant/specs/BugGate.tla", Code: "core", Language: language, Conformance: "driver.ts", Exhaustive: exhaustive}
	if language == "go" {
		manifest.Conformance = ""
		write857(t, dir, "go.mod", "module example.test/bugreplay\n\ngo 1.27.1\n")
		write857(t, dir, "core/core.go", "// +gobra\npackage core\n//@ ensures result >= 0\nfunc Safe() (result int) { return 0 }\n")
	} else {
		write857(t, dir, "core/core.ts", "export const n = 0;\n")
		write857(t, dir, "driver.ts", "import './core/core.ts';\n")
	}
	for name, v := range map[string]any{".invariant/invariant.json": manifest, ".invariant/ratified.lock": lock} {
		b, _ := json.Marshal(v)
		write857(t, dir, name, string(b))
	}
	write857(t, dir, manifest.Module, gateModel857)
	write857(t, dir, ".invariant/specs/Local.tla", includes["Local.tla"])
	write857(t, dir, "tools.jar", "test jar")
	exe, e := os.Executable()
	if e != nil {
		t.Fatal(e)
	}
	bin := t.TempDir()
	write857(t, bin, "docker", "#!/bin/sh\nexec '"+strings.ReplaceAll(exe, "'", "'\"'\"'")+"' \"$@\"\n")
	if e = os.Chmod(filepath.Join(bin, "docker"), 0700); e != nil {
		t.Fatal(e)
	}
	log := filepath.Join(dir, "commands.jsonl")
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	t.Setenv("INVARIANT_GATE857_DOUBLE", "1")
	t.Setenv("INVARIANT_GATE857_LOG", log)
	t.Setenv("INVARIANT_GATE857_NO_CODE", "")
	t.Setenv("INVARIANT_GATE857_MISS_BUG", "")
	t.Setenv("INVARIANT_GATE857_EXHAUSTIVE", "")
	if exhaustive {
		t.Setenv("INVARIANT_GATE857_EXHAUSTIVE", "1")
	}
	return dir, toolchain.Toolchain{JavaImage: "gate857-java", NodeImage: "gate857-node", GoImage: "gate857-go", GobraImage: "gate857-gobra", TLCJar: filepath.Join(dir, "tools.jar")}, log
}

func run857(t *testing.T, dir string, tc toolchain.Toolchain, model bool) *verify.Report {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	var r *verify.Report
	var err error
	if model {
		r, err = verify.RunModel(ctx, dir, tc)
	} else {
		r, err = verify.Run(ctx, dir, "", tc)
	}
	if err != nil || r == nil {
		t.Fatalf("gate didn't return evidence: %v %+v", err, r)
	}
	return r
}

func TestCurrentBugsBlockDriverGatesAndRetainIndependentPaths857(t *testing.T) {
	for _, exhaustive := range []bool{false, true} {
		dir, tc, _ := gateFixture857(t, "typescript", []string{"current", "current"}, exhaustive)
		r := run857(t, dir, tc, false)
		if r.Passed {
			t.Error("current bug obligations disappeared behind otherwise passing driver checks")
		}
		if !r.Design.Passed || !r.Build.Passed || r.Conformance == nil || !r.Conformance.Passed {
			t.Fatalf("independent successful evidence lost: %+v", r)
		}
		ids := map[string]bool{}
		for _, b := range r.Bugs {
			if !b.Caught || b.Replay == nil || !b.Replay.Required || b.Replay.Status != "replay-unavailable" || b.Replay.Passed {
				t.Fatalf("model detection treated as code replay: %+v", b)
			}
			if b.Replay.Counterexample == nil || len(b.Replay.Counterexample.Trace) != 4 {
				t.Fatalf("fresh TLC counterexample lost without outDir: %+v", b)
			}
			q := b.Replay.Request
			if q == nil || q.ID == "" || ids[q.ID] || q.Bug.Name != b.Name || q.Bug.CodeBehavior != "current" || q.Proposal != r.Proposal || len(q.Path.States) != 4 || len(q.Path.Steps) != 3 || q.Path.Offending != 2 {
				t.Fatalf("no-outDir run lost/crossed the complete obligation: %+v", q)
			}
			ids[q.ID] = true
			if q.Path.States[0]["n"].Atom != "0" || q.Path.Steps[0].Action != "Inc" || q.Path.Steps[1].Action != "Inc" || q.Path.Steps[2].Action != map[string]string{"BadA": "BreakA", "BadB": "BreakB"}[b.Name] {
				t.Errorf("substituted path: %+v", q.Path)
			}
		}
		if !strings.Contains(verify.Feedback(r), "replay-unavailable") {
			t.Fatal("builder feedback hides why the code gate cannot pass")
		}
	}
}

func TestModelOnlyPreparesCurrentReplayWithoutCode857(t *testing.T) {
	dir, tc, log := gateFixture857(t, "typescript", []string{"current", "hypothetical"}, false)
	t.Setenv("INVARIANT_GATE857_NO_CODE", "1")
	r := run857(t, dir, tc, true)
	if !r.Passed || !r.ModelOnly || !r.Bugs[0].Caught {
		t.Fatalf("replay unavailable changed model checking: %+v", r)
	}
	if r.Bugs[0].Replay == nil || r.Bugs[0].Replay.Request == nil || r.Bugs[0].Replay.Status != "pending" || r.Bugs[0].Replay.Passed {
		t.Fatalf("model check claims/lacks replay: %+v", r.Bugs[0])
	}
	if r.Bugs[1].Replay != nil && r.Bugs[1].Replay.Required {
		t.Fatal("hypothetical bug creates code obligation")
	}
	b, e := os.ReadFile(log)
	if e != nil {
		t.Fatal(e)
	}
	if strings.Contains(string(b), `"kind":"driver"`) || strings.Contains(string(b), `"kind":"proof"`) {
		t.Fatal("model-only invoked code")
	}
}

func TestLegacyAndMixedBugsKeepModelChecksWithoutInventedReplays857(t *testing.T) {
	dir, tc, log := gateFixture857(t, "typescript", []string{"", "hypothetical"}, false)
	r := run857(t, dir, tc, false)
	if !r.Passed {
		t.Fatalf("otherwise passing legacy sampled gate now fails: %+v", r)
	}
	view, _ := json.Marshal(r)
	if !strings.Contains(string(view), "not replayed: not classified") {
		t.Error("legacy report omits the exact non-replay label")
	}
	for _, b := range r.Bugs {
		if b.Replay != nil && (b.Replay.Required || b.Replay.Request != nil) {
			t.Errorf("invented replay obligation: %+v", b)
		}
	}
	calls, e := os.ReadFile(log)
	if e != nil {
		t.Fatal(e)
	}
	if strings.Contains(string(calls), "invariant-replay-v1") {
		t.Fatal("unclassified/hypothetical bug requested replay extraction")
	}
	t.Setenv("INVARIANT_GATE857_MISS_BUG", "1")
	if failed := run857(t, dir, tc, false); failed.Passed || failed.Bugs[0].Caught {
		t.Fatal("legacy model-strength failure no longer fails")
	}
	// An unclassified neighbor must not mask the mandatory current bug.
	dir, tc, _ = gateFixture857(t, "typescript", []string{"", "current"}, false)
	mixed := run857(t, dir, tc, false)
	if mixed.Passed || mixed.Bugs[1].Replay == nil || !mixed.Bugs[1].Replay.Required {
		t.Fatal("legacy neighbor masked current replay")
	}
	// Go continues to use its existing agreement/proof path.
	dir, tc, _ = gateFixture857(t, "go", []string{"current"}, false)
	goReport := run857(t, dir, tc, false)
	if !goReport.Passed || goReport.Agreement == nil || !goReport.Agreement.Passed || goReport.CodeAssurance() != "proved" {
		t.Fatalf("driver replay changed Go's gate: %+v", goReport)
	}
}

func TestLegacySampledExistingPythonStillPassesAndDoesNotReplay857(t *testing.T) {
	tc, log := pythongatetest.Fake(t)
	for _, explicit := range []bool{false, true} {
		f := pythongatetest.New(t, explicit, false)
		pythongatetest.Admit(t, f)
		r := pythongatetest.Run(t, f, tc)
		pythongatetest.Assert(t, f, r, true)
		b, _ := json.Marshal(r)
		if !strings.Contains(string(b), "not replayed: not classified") {
			t.Error("legacy Python gate omits classification status")
		}
		for _, bug := range r.Bugs {
			if bug.Replay != nil && (bug.Replay.Required || bug.Replay.Request != nil) {
				t.Fatal("legacy Python bug requested replay")
			}
		}
		t.Setenv("PA327_FAIL", "bug")
		failed := pythongatetest.Run(t, f, tc)
		if failed.Passed || failed.Bugs[0].Caught {
			t.Fatal("legacy Python model-strength refusal lost")
		}
		t.Setenv("PA327_FAIL", "")
	}
	b, e := os.ReadFile(log)
	if e != nil {
		t.Fatal(e)
	}
	if strings.Contains(string(b), "invariant-replay-v1") {
		t.Fatal("legacy existing-code gate called replay extraction")
	}
	// The application gate runs model checks first and clears ModelOnly
	// afterward: that transition must activate, not drop, current obligations.
	f := pythongatetest.New(t, false, false)
	for i := range f.Project.Lock.Statements {
		if f.Project.Lock.Statements[i].Kind == project.Bug {
			f.Project.Lock.Statements[i].CodeBehavior = "current"
		}
	}
	pythongatetest.Save(t, f)
	current := pythongatetest.Run(t, f, tc)
	if current.Passed || current.ModelOnly || current.Bugs[0].Replay == nil || !current.Bugs[0].Replay.Required || current.Bugs[0].Replay.Passed || current.Bugs[0].Replay.Status == "pending" {
		t.Fatalf("existing application dropped its mandatory obligation: %+v", current)
	}
}
